  const updated = await PATCH(request("http://localhost:3100", "/api/v1/account/preferences", legacy.cookie, "PATCH", { accountKey: body.data.key, expectedVersion: body.data.preference.version, appearance: "light" }));
  expect(updated.status).toBe(200);
  const { createAuth } = await import("@erpx/server-identity_access/adapters/auth");
