/** Isolated native SELECT instrumentation retains every original policy row.
 * The extra volatile branch returns no row, so it adds no Beta entitlement. */
async function adminBetaSourceProbe(companyId:string,body:string){
 const name='admin_beta_probe_'+randomUUID().replaceAll('-','');await env.H001_DB.exec(`CREATE SEQUENCE ${name}_fired;CREATE FUNCTION ${name}() RETURNS boolean LANGUAGE plpgsql AS $$ BEGIN PERFORM nextval('${name}_fired');${body};RETURN false;END $$;ALTER TABLE beta_policy RENAME TO ${name}_source;CREATE VIEW beta_policy AS SELECT * FROM ${name}_source UNION ALL SELECT '${companyId}'::text,0::bigint,0::bigint,0::bigint,0::bigint,0::bigint WHERE ${name}()`);return {name,cleanup:()=>env.H001_DB.exec(`DROP VIEW beta_policy;ALTER TABLE ${name}_source RENAME TO beta_policy;DROP FUNCTION ${name}();DROP SEQUENCE ${name}_fired`)};
}
