it("opens an original password recovery token on Account without requiring or creating a session", async () => {
  const { GET } = await import("@erpx/workplace/routes/api/auth/[...all]/route");
  const owner = await db.prepare('SELECT id FROM "user" WHERE email=?').bind(email).first<string>("id");
  const token = "account-recovery-" + randomUUID(), instant = Date.now();
  await db.prepare('INSERT INTO verification(id,identifier,value,"expiresAt","createdAt","updatedAt") VALUES(?,?,?,?,?,?)')
    .bind(randomUUID(), `reset-password:${token}`, owner, instant + 3600000, instant, instant).run();
  const before = await db.prepare('SELECT count(*)::int n FROM session WHERE "userId"=?').bind(owner).first("n");
  const response = await GET(request(issuer, `/api/auth/reset-password/${token}?callbackURL=` + encodeURIComponent(issuer + "/reset-password")));
  expect(response.status).toBe(302);
  const destination = new URL(response.headers.get("location")!);
  expect(destination.origin).toBe(issuer);
  expect(destination.pathname).toBe("/reset-password");
  expect(destination.searchParams.get("token")).toBe(token);
  expect(await db.prepare('SELECT count(*)::int n FROM session WHERE "userId"=?').bind(owner).first("n")).toBe(before);
  expect(await db.prepare("SELECT value FROM verification WHERE identifier=?").bind(`reset-password:${token}`).first("value")).toBe(owner);
  expect((await GET(request(issuer, "/api/auth/list-sessions"))).status).toBe(401);
});
